import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { apiMethods, apiUtils } from '../services/api';

const AuthContext = createContext();

const authReducer = (state, action) => {
  switch (action.type) {
    case 'LOGIN_START':
      return {
        ...state,
        loading: true,
        error: null
      };
    
    case 'LOGIN_SUCCESS':
      return {
        ...state,
        loading: false,
        isAuthenticated: true,
        user: action.payload,
        error: null
      };
    
    case 'LOGIN_FAILURE':
      return {
        ...state,
        loading: false,
        isAuthenticated: false,
        user: null,
        error: action.payload
      };
    
    case 'LOGOUT':
      return {
        ...state,
        isAuthenticated: false,
        user: null,
        error: null
      };
    
    case 'CLEAR_ERROR':
      return {
        ...state,
        error: null
      };
    
    case 'LOAD_USER':
      return {
        ...state,
        isAuthenticated: !!action.payload,
        user: action.payload,
        loading: false
      };
    
    default:
      return state;
  }
};

export const AuthProvider = ({ children }) => {
  const [state, dispatch] = useReducer(authReducer, {
    isAuthenticated: false,
    user: null,
    loading: true,
    error: null
  });

  // Load user from localStorage on initialization
  useEffect(() => {
    try {
      const savedUser = localStorage.getItem('user');
      const user = savedUser ? JSON.parse(savedUser) : null;
      dispatch({ type: 'LOAD_USER', payload: user });
    } catch (error) {
      console.error('Error loading user from localStorage:', error);
      dispatch({ type: 'LOAD_USER', payload: null });
    }
  }, []);

  const login = async (credentials) => {
    dispatch({ type: 'LOGIN_START' });
    
    try {
      const response = await apiMethods.users.login(credentials);
      
      if (response.data.success) {
        const { user, token } = response.data.data;
        
        // Store token and user
        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(user));
        
        dispatch({ type: 'LOGIN_SUCCESS', payload: user });
        
        return { success: true, user };
      } else {
        throw new Error(response.data.error || 'Login failed');
      }
    } catch (error) {
      const errorMessage = apiUtils.getErrorMessage(error);
      dispatch({ type: 'LOGIN_FAILURE', payload: errorMessage });
      return { success: false, error: errorMessage };
    }
  };

  const register = async (userData) => {
    dispatch({ type: 'LOGIN_START' });
    
    try {
      const response = await apiMethods.users.register(userData);
      
      if (response.data.success) {
        const { user, token } = response.data.data;
        
        // Store token and user
        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(user));
        
        dispatch({ type: 'LOGIN_SUCCESS', payload: user });
        
        return { success: true, user };
      } else {
        throw new Error(response.data.error || 'Registration failed');
      }
    } catch (error) {
      const errorMessage = apiUtils.getErrorMessage(error);
      dispatch({ type: 'LOGIN_FAILURE', payload: errorMessage });
      return { success: false, error: errorMessage };
    }
  };

  const signup = async (userData) => {
    dispatch({ type: 'LOGIN_START' });
    
    try {
      const response = await apiMethods.users.signup(userData);
      
      if (response.data.success) {
        const { user, token } = response.data.data;
        
        // Store token and user
        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(user));
        
        dispatch({ type: 'LOGIN_SUCCESS', payload: user });
        
        return { success: true, user };
      } else {
        throw new Error(response.data.error || 'Signup failed');
      }
    } catch (error) {
      const errorMessage = apiUtils.getErrorMessage(error);
      dispatch({ type: 'LOGIN_FAILURE', payload: errorMessage });
      return { success: false, error: errorMessage };
    }
  };

  const socialLogin = async (provider) => {
    dispatch({ type: 'LOGIN_START' });
    
    try {
      // Simulate social login
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      const user = {
        id: Date.now(),
        email: `demo.${provider.toLowerCase()}@example.com`,
        name: `Demo User (${provider})`,
        avatar: null,
        provider: provider.toLowerCase(),
        loginTime: new Date().toISOString()
      };
      
      localStorage.setItem('user', JSON.stringify(user));
      dispatch({ type: 'LOGIN_SUCCESS', payload: user });
      
      return { success: true, user };
    } catch (error) {
      const errorMessage = error.message || `${provider} login failed`;
      dispatch({ type: 'LOGIN_FAILURE', payload: errorMessage });
      return { success: false, error: errorMessage };
    }
  };

  const logout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('token');
    dispatch({ type: 'LOGOUT' });
  };

  const clearError = () => {
    dispatch({ type: 'CLEAR_ERROR' });
  };

  const updateUser = async (userData) => {
    try {
      const response = await apiMethods.users.updateProfile(userData);
      
      if (response.data.success) {
        const { user } = response.data.data;
        localStorage.setItem('user', JSON.stringify(user));
        dispatch({ type: 'LOGIN_SUCCESS', payload: user });
        return { success: true, user };
      } else {
        throw new Error(response.data.error || 'Profile update failed');
      }
    } catch (error) {
      console.error('Profile update failed:', error);
      return { success: false, error: apiUtils.getErrorMessage(error) };
    }
  };

  const isLoggedIn = () => {
    return state.isAuthenticated && state.user !== null;
  };

  const requireAuth = () => {
    return state.isAuthenticated;
  };

  const value = {
    ...state,
    login,
    register,
    signup,
    socialLogin,
    logout,
    clearError,
    updateUser,
    isLoggedIn,
    requireAuth
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export default AuthContext;
